"""A tiny Caesar cipher utility."""


def encrypt(text: str, shift: int) -> str:
    """Return *text* with each character shifted by *shift* positions."""
    result = []
    normalized_shift = shift % 26
    for char in text:
        if "a" <= char <= "z":
            start = ord("a")
            result.append(chr(start + (ord(char) - start + normalized_shift) % 26))
        elif "A" <= char <= "Z":
            start = ord("A")
            result.append(chr(start + (ord(char) - start + normalized_shift) % 26))
        else:
            result.append(char)
    return "".join(result)
